/**
 * Contract drift detection.
 *
 * `src/api/types.ts` is hand-written (see the reasoning there and in the
 * roadmap: generation is milestone 1.15). These tests validate those types
 * against the backend's **real** OpenAPI schema, committed as
 * `openapi.snapshot.json` and regenerated by `make openapi`.
 *
 * So a backend change that renames a field, changes a type, or removes an
 * endpoint the client consumes fails here — which is the property generation
 * would buy. What it does not buy is the generation itself; that stays
 * deferred rather than silently taken over.
 *
 * The chain that makes this honest:
 *
 *   1. `scripts/openapi-snapshot.sh --check` fails CI if the snapshot is stale
 *      relative to the live FastAPI app.
 *   2. These tests fail if the snapshot disagrees with the client's types.
 *
 * Either link breaking is a failure, so the types cannot drift from the server
 * without someone being told.
 */

import { describe, expect, it } from 'vitest';

import schema from '@/api/openapi.snapshot.json';
import { API_BASE_PATH } from '@/api/client';
import type {
  AccountDetails,
  ApiInfo,
  AuditEvent,
  AuditEventList,
  CurrentUser,
  Host,
  HostConnectivity,
  HostLifecycle,
  HostListResult,
  HostRevocationResult,
  IssuedEnrollment,
  LogoutResult,
  ManagedUser,
  OwnSession,
  OwnSessionList,
  PasswordChangeResult,
  SessionRevocationResult,
  SetupStatus,
  UserListResult,
  UserRole,
} from '@/api/types';

type JsonSchema = {
  type?: string;
  properties?: Record<string, JsonSchema>;
  required?: string[];
  enum?: unknown[];
  $ref?: string;
  anyOf?: JsonSchema[];
  const?: unknown;
};

type OpenApiDocument = {
  paths: Record<
    string,
    Record<
      string,
      {
        responses: Record<
          string,
          { content?: Record<string, { schema?: { $ref?: string } }> }
        >;
        requestBody?: { content?: Record<string, { schema?: { $ref?: string } }> };
      }
    >
  >;
  components: { schemas: Record<string, JsonSchema> };
};

const document = schema as unknown as OpenApiDocument;

/** Resolve a `#/components/schemas/Name` reference. */
function resolve(ref: string): JsonSchema {
  const name = ref.replace('#/components/schemas/', '');
  const resolved = document.components.schemas[name];
  expect(resolved, `schema ${name} is missing from the snapshot`).toBeDefined();
  return resolved!;
}

/** The success-response schema for an operation, at a given status. */
function responseSchemaAt(path: string, method: string, status: string): JsonSchema {
  const operation = document.paths[path]?.[method];
  expect(operation, `${method.toUpperCase()} ${path} is not in the schema`).toBeDefined();
  const ref = operation?.responses[status]?.content?.['application/json']?.schema?.$ref;
  expect(
    ref,
    `${method.toUpperCase()} ${path} has no ${status} JSON schema`,
  ).toBeDefined();
  return resolve(ref!);
}

/** The 200-response schema for an operation. */
function responseSchema(path: string, method: string): JsonSchema {
  return responseSchemaAt(path, method, '200');
}

/** Flatten `anyOf` so a nullable field reports its underlying types. */
function typesOf(property: JsonSchema): string[] {
  if (property.anyOf) return property.anyOf.flatMap(typesOf);
  if (property.$ref) return typesOf(resolve(property.$ref));
  if (property.const !== undefined) return [typeof property.const];
  return property.type ? [property.type] : [];
}

/**
 * Assert the server's schema has exactly the properties the client's type
 * declares, with compatible primitive types.
 *
 * Exactness in both directions is deliberate. A missing property breaks the
 * client; an *extra* one is how a new field — possibly a sensitive one, as
 * `/setup/status` shows — reaches the browser without anyone deciding it
 * should.
 */
/**
 * The JSON Schema type names this file compares against.
 *
 * `integer` is distinct from `number` in JSON Schema and FastAPI emits it for
 * every `int` field, so collapsing the two here would make a count that became
 * a float pass unnoticed.
 */
type SchemaKind = 'string' | 'boolean' | 'number' | 'integer' | 'array' | 'object';

function expectContract(
  schemaUnderTest: JsonSchema,
  expected: Record<string, SchemaKind>,
): void {
  const actual = schemaUnderTest.properties ?? {};

  expect(Object.keys(actual).sort()).toEqual(Object.keys(expected).sort());

  for (const [field, kind] of Object.entries(expected)) {
    expect(typesOf(actual[field]!), `field ${field}`).toContain(kind);
  }
}

describe('API base path', () => {
  it('matches the versioned prefix the backend serves', () => {
    // Every path in the schema that is not an operational probe lives under
    // this prefix, so a mismatch would make every client call a 404.
    const productPaths = Object.keys(document.paths).filter(
      (path) => !['/healthz', '/readyz'].includes(path),
    );

    expect(productPaths.length).toBeGreaterThan(0);
    for (const path of productPaths) {
      expect(path.startsWith(API_BASE_PATH)).toBe(true);
    }
  });
});

describe('GET /auth/me contract', () => {
  it('returns every field CurrentUser declares, and no others', () => {
    const contract: Record<keyof CurrentUser, 'string' | 'boolean'> = {
      user_id: 'string',
      username: 'string',
      display_name: 'string',
      role: 'string',
      is_active: 'boolean',
      session_expires_at: 'string',
      csrf_token: 'string',
    };

    expectContract(responseSchema('/api/v1/auth/me', 'get'), contract);
  });

  it('requires the fields the client reads unconditionally', () => {
    const required = responseSchema('/api/v1/auth/me', 'get').required ?? [];

    // The auth state machine reads these without a null check.
    expect(required).toContain('username');
    expect(required).toContain('role');
    expect(required).toContain('is_active');
    expect(required).toContain('csrf_token');
  });
});

describe('POST /auth/login contract', () => {
  it('accepts exactly the credentials the client sends', () => {
    const operation = document.paths['/api/v1/auth/login']?.post;
    const ref = operation?.requestBody?.content?.['application/json']?.schema?.$ref;
    expect(ref).toBeDefined();

    const body = resolve(ref!);

    expect(Object.keys(body.properties ?? {}).sort()).toEqual(['password', 'username']);
    expect((body.required ?? []).sort()).toEqual(['password', 'username']);
  });

  it('returns the same shape as /auth/me', () => {
    // The client reuses CurrentUser for both, so they must agree.
    const loginRef =
      document.paths['/api/v1/auth/login']?.post?.responses['200']?.content?.[
        'application/json'
      ]?.schema?.$ref;
    const meRef =
      document.paths['/api/v1/auth/me']?.get?.responses['200']?.content?.[
        'application/json'
      ]?.schema?.$ref;

    expect(loginRef).toBe(meRef);
  });
});

describe('POST /auth/logout contract', () => {
  it('returns the status field LogoutResult declares', () => {
    const contract: Record<keyof LogoutResult, 'string'> = { status: 'string' };

    expectContract(responseSchema('/api/v1/auth/logout', 'post'), contract);
  });
});

describe('GET /setup/status contract', () => {
  it('returns exactly one boolean', () => {
    const contract: Record<keyof SetupStatus, 'boolean'> = { initialized: 'boolean' };

    expectContract(responseSchema('/api/v1/setup/status', 'get'), contract);
  });

  it('discloses nothing else', () => {
    // This endpoint is public. A new field here is a new unauthenticated
    // disclosure, so the contract is pinned on the client side too — not
    // only in the backend's own tests.
    const properties = Object.keys(responseSchema('/api/v1/setup/status', 'get').properties ?? {});

    expect(properties).toEqual(['initialized']);
  });
});

describe('GET /info contract', () => {
  it('matches ApiInfo', () => {
    const contract: Record<keyof ApiInfo, 'string'> = {
      api_version: 'string',
      server_version: 'string',
      environment: 'string',
    };

    expectContract(responseSchema('/api/v1/info', 'get'), contract);
  });
});

describe('role enum', () => {
  it('has exactly the three roles the client knows about', () => {
    // A fourth role appearing server-side must not be silently treated as
    // one of these. ADR-013 makes adding one a reviewed migration; this makes
    // it a reviewed client change too.
    const role = document.components.schemas.UserRole;
    const values = role?.enum ?? [];

    const known: UserRole[] = ['viewer', 'operator', 'admin'];
    expect([...values].sort()).toEqual([...known].sort());
  });
});

/* -------------------------------------------------------------------------
 * User administration, account and audit (milestone 1.7)
 * ---------------------------------------------------------------------- */

describe('GET /users contract', () => {
  it('matches UserListResult', () => {
    const contract: Record<keyof UserListResult, SchemaKind> = {
      items: 'array',
      // `integer`, not `number`: FastAPI emits the distinction and the
      // assertion keeps it, so a count that quietly became a float would fail
      // here rather than render as "2.0 accounts".
      total: 'integer',
      limit: 'integer',
      offset: 'integer',
    };

    expectContract(responseSchema('/api/v1/users', 'get'), contract);
  });

  it('returns exactly the fields ManagedUser declares, and no others', () => {
    // The response model is an allow-list rather than a serialised row, and
    // this is the client-side half of keeping it that way: an added server
    // field — a password hash, a canonical username — fails here before it
    // can reach a browser.
    const contract: Record<keyof ManagedUser, SchemaKind> = {
      user_id: 'string',
      username: 'string',
      display_name: 'string',
      role: 'string',
      is_active: 'boolean',
      created_at: 'string',
      last_login_at: 'string',
      active_session_count: 'integer',
    };

    expectContract(resolve('#/components/schemas/UserResponse'), contract);
  });

  it('never advertises a password or a canonical username', () => {
    const properties = Object.keys(
      resolve('#/components/schemas/UserResponse').properties ?? {},
    );

    expect(properties).not.toContain('password');
    expect(properties).not.toContain('password_hash');
    expect(properties).not.toContain('username_canonical');
  });

  it('accepts the filters the client sends', () => {
    // The client builds a query string by hand, so a renamed parameter would
    // silently stop filtering rather than fail — the list would just look
    // wrong.
    const parameters = (
      document.paths['/api/v1/users']?.get as unknown as {
        parameters?: { name: string }[];
      }
    ).parameters;
    const names = (parameters ?? []).map((parameter) => parameter.name);

    expect(names).toEqual(
      expect.arrayContaining(['search', 'role', 'is_active', 'limit', 'offset']),
    );
  });
});

describe('POST /users contract', () => {
  it('accepts exactly the fields the client sends', () => {
    const ref =
      document.paths['/api/v1/users']?.post?.requestBody?.content?.['application/json']
        ?.schema?.$ref;
    expect(ref).toBeDefined();

    const body = resolve(ref!);

    expect(Object.keys(body.properties ?? {}).sort()).toEqual([
      'display_name',
      'is_active',
      'password',
      'role',
      'username',
    ]);
    // Only the two that have no sensible default are required; the client
    // relies on the server defaulting the role to viewer.
    expect((body.required ?? []).sort()).toEqual(['password', 'username']);
  });

  it('creates with 201, not 200', () => {
    // The client does not branch on it, but a change here would mean the
    // helper's declared return type no longer matched a 200-only contract.
    const responses = Object.keys(document.paths['/api/v1/users']?.post?.responses ?? {});

    expect(responses).toContain('201');
  });
});

describe('PATCH /users/{id} contract', () => {
  it('accepts only the three mutable fields', () => {
    // `username` must be absent: usernames are immutable (ADR-041), and a
    // field appearing here would mean that decision had been reversed without
    // the client being told.
    const ref =
      document.paths['/api/v1/users/{user_id}']?.patch?.requestBody?.content?.[
        'application/json'
      ]?.schema?.$ref;
    expect(ref).toBeDefined();

    const body = resolve(ref!);

    expect(Object.keys(body.properties ?? {}).sort()).toEqual([
      'display_name',
      'is_active',
      'role',
    ]);
    // Nothing is required: a partial update names only what it changes.
    expect(body.required ?? []).toEqual([]);
  });
});

